package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class UpperGroupedEstimationTest {
 @Test public void all400ConditionsPreserveOwnGuessAndOnlyScorePublicCount(){Generator g=new Generator(new Random(128));var limits=GlobalCurriculum.limits("england-primary-2021-v1",GroupedEstimation.ID,3);List<String> recent=new ArrayList<>();Set<Integer> counts=new HashSet<>();for(int i=0;i<400;i++){Question q=g.next(GroupedEstimation.ID,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int count=CollectionGrouping.points(q,0).length;counts.add(count);Learning.Session s=new Learning.Session();s.question=q;s.answers.add(i%2==0?"0":"999");s.studyMs=12345;assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),s.answers).status);String guess=s.answers.get(0),signature=q.signature();assertTrue(GroupedEstimation.beginCounting(s));assertEquals(guess,q.learnerEstimate);assertEquals("",s.answers.get(0));assertFalse(s.hadError);assertEquals(12345,s.studyMs);assertEquals(signature,q.signature());q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(""+count)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(count+1))).status);GroupedEstimation.attach(q);HelpPlan p=HelpPlan.forQuestion(q);int[] expected={count/5,count%5,count};for(int k=0;k<3;k++)assertTrue(p.step(k).accepts(""+expected[k]));assertFalse(p.canTransfer());assertEquals(count,CollectionGrouping.points(q,5).length);assertEquals(count>30?Math.min(5,(count+4)/5):Math.min(10,(count+4)/5),CollectionGrouping.columns(q,(count+4)/5));Learning.State state=new Learning.State();state.session=s;Learning.State saved=LearningSnapshot.capture(state);assertEquals(guess,saved.session.question.learnerEstimate);}assertEquals(100,counts.size());assertEquals(recent.get(0),g.next(GroupedEstimation.ID,recent,false,limits).signature());Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(p).inGrade(GroupedEstimation.ID,3));}
 @Test public void malformedPublicCollectionCannotUseAHiddenKey(){Question q=new Question(GroupedEstimation.ID,"","","100");q.learnerEstimate="0";q.diagram=new StudyDiagram("countCollection",new double[]{100,0},"5");assertTrue(new Checker().check(q,List.of(),List.of("100")).correct());q.diagram.values[0]=101;assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("100")).status);q.diagram.values[0]=Double.NaN;assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("100")).status);q.diagram.values[0]=100;q.diagram.values[1]=4;assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("100")).status);}
}
